from __future__ import annotations

import os
import zlib

from . import config, utils


def read(db_name: str, *, start: int = None, end: int = None) -> bytes:
    json_path, json_exists, ddb_path, ddb_exists = utils.file_info(db_name)

    if json_exists:
        if ddb_exists:
            raise FileExistsError(f'Inconsistent: "{db_name}" exists as .json and .ddb. Please remove one of them.')
        with open(json_path, "rb") as file_handle:
            if start is None and end is None:
                return file_handle.read()
            start = start or 0
            file_handle.seek(start)
            if end is None:
                return file_handle.read()
            return file_handle.read(end - start)

    if not ddb_exists:
        raise FileNotFoundError(f'No database file exists for "{db_name}"')

    with open(ddb_path, "rb") as file_handle:
        json_bytes = zlib.decompress(file_handle.read())
        if start is None and end is None:
            return json_bytes
        start = start or 0
        end = end or len(json_bytes)
        return json_bytes[start:end]


def write(db_name: str, dump: bytes, *, start: int = None) -> None:
    json_path, json_exists, ddb_path, ddb_exists = utils.file_info(db_name)

    remove_file = None
    if config.use_compression:
        if start is not None:
            raise RuntimeError("Cannot write to compressed file at a specific index")
        write_file = ddb_path
        if json_exists:
            remove_file = json_path
        payload = zlib.compress(dump, 1)
    else:
        write_file = json_path
        if ddb_exists:
            remove_file = ddb_path
        payload = dump

    os.makedirs(os.path.dirname(write_file), exist_ok=True)

    if start is None:
        with open(write_file, "wb") as file_handle:
            file_handle.write(payload)
    else:
        mode = "r+b" if os.path.exists(write_file) else "wb"
        with open(write_file, mode) as file_handle:
            file_handle.seek(start)
            file_handle.truncate()
            file_handle.write(payload)

    if remove_file is not None and os.path.exists(remove_file):
        os.remove(remove_file)

