from __future__ import annotations

import os
from typing import Union

import orjson

from . import config


class Indexer:
    __slots__ = ("data", "path")

    def __init__(self, db_name: str) -> None:
        db_name = str(db_name).replace("\\", "/").replace("/", "___")
        self.path = os.path.join(config.storage_directory, ".ddb", f"{db_name}.index")

        os.makedirs(os.path.dirname(self.path), exist_ok=True)
        if not os.path.exists(self.path):
            self.data = {}
            return

        try:
            with open(self.path, "rb") as file_handle:
                self.data = orjson.loads(file_handle.read())
        except orjson.JSONDecodeError:
            self.data = {}

    def get(self, key: str) -> Union[list, None]:
        return self.data.get(key, None)

    def write(
        self,
        key: str,
        start_index: int,
        end_index: int,
        indent_level: int,
        indent_with: str,
        value_hash: str,
        old_value_end: int,
    ) -> None:
        if self.data.get(key) is not None:
            delta = end_index - old_value_end
            if delta:
                for other_key, entry in self.data.items():
                    if other_key == key:
                        continue
                    if entry[0] > old_value_end:
                        entry[0] += delta
                        entry[1] += delta

        self.data[key] = [start_index, end_index, indent_level, indent_with, value_hash]
        temp_path = f"{self.path}.tmp"
        with open(temp_path, "wb") as file_handle:
            file_handle.write(orjson.dumps(self.data))
        os.replace(temp_path, self.path)

