from __future__ import annotations

import glob
import os
from typing import Tuple

from . import byte_codes, config


def _normalize_db_name(db_name: str | os.PathLike[str]) -> str:
    value = os.fspath(db_name).replace("\\", "/")
    while "//" in value:
        value = value.replace("//", "/")
    return value.strip("/")


def _get_storage_path(db_name: str | os.PathLike[str]) -> str:
    normalized = _normalize_db_name(db_name)
    parts = [part for part in normalized.split("/") if part and part != "."]
    if not parts:
        return config.storage_directory
    return os.path.join(config.storage_directory, *parts)


def _resolve_relative_path(db_name: str | os.PathLike[str]) -> str:
    return os.path.abspath(_get_storage_path(db_name))


def file_info(db_name: str) -> Tuple[str, bool, str, bool]:
    base = _get_storage_path(db_name)
    json_path = f"{base}.json"
    ddb_path = f"{base}.ddb"
    return json_path, os.path.exists(json_path), ddb_path, os.path.exists(ddb_path)


def file_exists(db_name: str) -> bool:
    _, json_exists, _, ddb_exists = file_info(db_name)
    return json_exists or ddb_exists


def find_all(file_name: str) -> list[str]:
    base_pattern = _get_storage_path(file_name)
    files_all = glob.glob(f"{base_pattern}.ddb")
    files_all += glob.glob(f"{base_pattern}.json")

    normalized: list[str] = []
    for path in sorted(files_all):
        if path.endswith(".ddb"):
            path = path[:-4]
        elif path.endswith(".json"):
            path = path[:-5]
        path = os.path.relpath(path, config.storage_directory).replace(os.sep, "/")
        normalized.append(path)
    return normalized


def seek_index_through_value_bytes(json_bytes: bytes, index: int) -> int:
    list_depth = 0
    dict_depth = 0
    i = index
    len_json_bytes = len(json_bytes)

    while i < len_json_bytes:
        current = json_bytes[i]
        if current == byte_codes.BACKSLASH:
            i += 1
        elif current == byte_codes.QUOTE:
            while True:
                i = json_bytes.find(byte_codes.QUOTE, i + 1)
                if i == -1:
                    raise TypeError("Invalid JSON")

                j = i - 1
                backslash_count = 0
                while j >= 0 and json_bytes[j] == byte_codes.BACKSLASH:
                    backslash_count += 1
                    j -= 1
                if backslash_count % 2 == 0:
                    break

            if list_depth == 0 and dict_depth == 0:
                return i + 1
        elif current == byte_codes.OPEN_SQUARE:
            list_depth += 1
        elif current == byte_codes.OPEN_CURLY:
            dict_depth += 1
        elif current == byte_codes.CLOSE_SQUARE:
            list_depth -= 1
            if list_depth == 0 and dict_depth <= 0:
                return i + 1 + dict_depth
        elif current == byte_codes.CLOSE_CURLY:
            dict_depth -= 1
            if dict_depth <= 0 and list_depth == 0:
                return i + 1 + dict_depth
        elif list_depth == 0:
            if dict_depth == -1:
                return i
            if dict_depth == 0 and current in (byte_codes.COMMA, byte_codes.NEWLINE):
                return i
        i += 1

    raise TypeError("Invalid JSON")


def count_nesting_in_bytes(json_bytes: bytes, start: int, end: int) -> int:
    i = start
    nesting = 0
    while (i := json_bytes.find(byte_codes.OPEN_CURLY, i, end)) != -1:
        if i == 0 or json_bytes[i - 1] != byte_codes.BACKSLASH:
            nesting += 1
        i += 1
    i = start
    while (i := json_bytes.find(byte_codes.CLOSE_CURLY, i, end)) != -1:
        if i == 0 or json_bytes[i - 1] != byte_codes.BACKSLASH:
            nesting -= 1
        i += 1
    return nesting


def find_outermost_key_in_json_bytes(json_bytes: bytes, key: str) -> Tuple[int, int]:
    key_bytes = f'"{key}":'.encode()
    if (curr_i := json_bytes.find(key_bytes, 0)) == -1:
        return (-1, -1)

    key_nest = [(curr_i, count_nesting_in_bytes(json_bytes, 0, curr_i))]
    while (next_i := json_bytes.find(key_bytes, curr_i + len(key_bytes))) != -1:
        nesting = count_nesting_in_bytes(json_bytes, curr_i + len(key_bytes), next_i)
        key_nest.append((next_i, nesting))
        curr_i = next_i

    if len(key_nest) == 1:
        index, level = key_nest[0]
        return (index, index + len(key_bytes)) if level == 1 else (-1, -1)

    total_nesting: list[tuple[int, int]] = [key_nest[0]]
    for i in range(1, len(key_nest)):
        total_nesting.append((key_nest[i][0], total_nesting[i - 1][1] + key_nest[i][1]))

    indices_at_level_one = [index for index, level in total_nesting if level == 1]
    if len(indices_at_level_one) != 1:
        return (-1, -1)
    start = indices_at_level_one[0]
    return start, start + len(key_bytes)


def detect_indentation_in_json_bytes(json_bytes: bytes, index: int) -> Tuple[int, str]:
    indentation_values: list[int] = []
    for i in range(index - 1, -1, -1):
        if json_bytes[i] not in (byte_codes.SPACE, byte_codes.TAB):
            break
        indentation_values.append(json_bytes[i])

    if not indentation_values:
        return 0, ""

    indentation_bytes = bytes(reversed(indentation_values))
    if byte_codes.TAB in indentation_bytes:
        return len(indentation_bytes), "\t"

    if isinstance(config.indent, int) and config.indent > 0:
        return len(indentation_bytes) // config.indent, " " * config.indent

    if isinstance(config.indent, str) and config.indent:
        unit = config.indent
        return len(indentation_bytes) // len(unit.encode()), unit

    if len(indentation_bytes) >= 2:
        return len(indentation_bytes) // 2, "  "
    return 1, " "

