from __future__ import annotations

# See: https://www.charset.org/utf-8
BACKSLASH = 92
QUOTE = 34
OPEN_SQUARE = 91
CLOSE_SQUARE = 93
OPEN_CURLY = 123
CLOSE_CURLY = 125
SPACE = 32
TAB = 9
NEWLINE = 10
COMMA = 44
COLON = 58


def is_object_start(code: int) -> bool:
    return code == OPEN_CURLY


def is_array_start(code: int) -> bool:
    return code == OPEN_SQUARE


def _to_key_bytes(key: bytes | str) -> bytes:
    return key if isinstance(key, bytes) else str(key).encode()


def find_key_in_json_bytes(json_bytes: bytes, key: bytes | str) -> int:
    key_bytes = _to_key_bytes(key)
    return json_bytes.find(b'"' + key_bytes + b'"')


def find_value_start(json_bytes: bytes, index: int) -> int:
    while index < len(json_bytes) and json_bytes[index] in (SPACE, TAB, NEWLINE, COLON):
        index += 1
    return index


def extract_value_bytes(json_bytes: bytes, key_index: int) -> bytes | None:
    colon_index = json_bytes.find(b":", key_index)
    if colon_index == -1:
        return None
    from . import utils

    start = find_value_start(json_bytes, colon_index)
    end = utils.seek_index_through_value_bytes(json_bytes, start)
    return json_bytes[start:end]

